
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_am05_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_am05", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.167280711756613e+00, -4.083491587062633e+00, -3.966108060939689e+00, -3.803561458909497e+00, -3.582213756248066e+00, -3.287982613095987e+00, -2.910273309514811e+00, -2.449413012748310e+00, -1.927909068022304e+00, -1.400300149714680e+00, -9.403437750206460e-01, -6.763081141726028e-01, -5.895825748003989e-01, -4.741504848856375e-01, -3.322008999557729e-01, -2.058833092769164e-01, -1.201566322294216e-01, -6.972802928246399e-02, -4.110398995575025e-02, -2.497669117236744e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


